package me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc;import static me.neobliz1.ecomonitoring.platform.common.util.PlatformCommonUtils.expandRequestSpatialBoxByTier;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.QUERIES_GLOBAL_REGION;import static me.neobliz1.ecomonitoring.platform.history.domain.port.service.HistoricalUtils.getBucketIdFromSpatialBoxRequest;import static me.neobliz1.ecomonitoring.platform.history.domain.port.service.HistoricalUtils.getL1BucketCache;import io.github.neobliz1.validproto.annotation.ValidProto;import io.github.neobliz1.validproto.annotation.ValidatedProto;import io.grpc.Status;import io.grpc.StatusRuntimeException;import io.grpc.stub.StreamObserver;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import me.neobliz1.ecomonitoring.platform.history.domain.model.dto.WeatherMapBucketCacheDto;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherGridCellLayer;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherMapBucket;import me.neobliz1.ecomonitoring.platform.history.domain.port.inbound.HistoricalDataConvertService;import me.neobliz1.ecomonitoring.platform.history.domain.port.outbound.HistoricalQueryRepository;import me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc.record.SpatialQueryKey;import me.neobliz1.ecomonitoring.platform.model.exception.L1CacheNotAvailableException;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.GridCellLayers;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.WeatherMap;import org.jspecify.annotations.NonNull;import org.springframework.cache.Cache;import org.springframework.cache.CacheManager;import weather.history.HistoryServiceGrpc;import weather.history.SpatialBoxRequest;import java.util.List;import java.util.Map;import java.util.Optional;import java.util.UUID;import java.util.stream.Collectors;@Slf4j@ValidatedProto@RequiredArgsConstructorpublic class HistoricalExternalCommunicationObserver extends HistoryServiceGrpc.HistoryServiceImplBase {    private final HistoricalQueryRepository historicalQueryRepository;    private final HistoricalDataConvertService weatherMapConverter;    private final CacheManager springL1CacheManager;    @Override    public void findFilteredGridDataBySpatialBox(@ValidProto SpatialBoxRequest request, StreamObserver<WeatherMap> responseObserver) {        if(log.isDebugEnabled()) {            log.debug("GRPC request: {} [{}#{}#{}#{}] has been received and is processing.",                    request.getTimestampBucket(), request.getMinLat(), request.getMaxLat(), request.getMinLon(), request.getMaxLon());        }        getGridDataBySpatialBox(responseObserver, request);    }    private void getGridDataBySpatialBox(@NonNull StreamObserver<WeatherMap> responseObserver, @NonNull SpatialBoxRequest request) {        try {            SpatialQueryKey queryKey = createSpatialQueryKeyBasedOnRequest(request);            Optional<WeatherMap> optionalCache = tryToGetMapFromCacheByQueryKey(queryKey);            if(optionalCache.isPresent()) {                proceedSuccessResponse(responseObserver, optionalCache.get());                return;            }            WeatherMap weatherMap = getWeatherMapFromDb(request);            if(log.isDebugEnabled()) {                log.debug("WeatherMap successfully built for request [{}]: Found {} unique grid cell(s).", queryKey, weatherMap.getGridCellsCount());            }            getGrpcQueryCache().put(queryKey, weatherMap);            proceedSuccessResponse(responseObserver, weatherMap);        } catch(StatusRuntimeException e) {            proceedFailedResponse(responseObserver, e,                    String.format("Spatial box lookup failed with explicit status: %s", e.getStatus()));        } catch(Exception e) {            Throwable cause = e.getCause();            proceedFailedResponse(responseObserver, e,                    String.format("Unexpected error processing spatial box request: %s, cause: %s", e.getMessage(), cause==null?"":cause.getMessage()));        }    }    private Optional<WeatherMap> tryToGetMapFromCacheByQueryKey(@NonNull SpatialQueryKey queryKey) {        Cache grpcQueryCache = getGrpcQueryCache();        WeatherMap cachedResponse = grpcQueryCache.get(queryKey, WeatherMap.class);        if(cachedResponse==null) {            return Optional.empty();        }        if(log.isDebugEnabled()) {            log.debug("Mux Performance Hit! Serving complete WeatherMap Protobuf array directly from shared L1 cache memory.");        }        return Optional.of(cachedResponse);    }    private @NonNull SpatialQueryKey createSpatialQueryKeyBasedOnRequest(@NonNull SpatialBoxRequest request) {        return new SpatialQueryKey(                request.getTimestampBucket(),                request.getTimeIntervalInMinutes(),                request.getMinLat(),                request.getMaxLat(),                request.getMinLon(),                request.getMaxLon()        );    }    private @NonNull Cache getGrpcQueryCache() {        Cache grpcQueryCache = springL1CacheManager.getCache(QUERIES_GLOBAL_REGION);        if(grpcQueryCache==null) {            throw new L1CacheNotAvailableException(QUERIES_GLOBAL_REGION);        }        return grpcQueryCache;    }    private void proceedSuccessResponse(StreamObserver<WeatherMap> responseObserver, WeatherMap weatherMap) {        responseObserver.onNext(weatherMap);        responseObserver.onCompleted();    }    private @NonNull WeatherMap getWeatherMapFromDb(@NonNull SpatialBoxRequest request) {        List<WeatherGridCellLayer> weatherGridCells = getGridCellLayersWithExpandedAlgorithmIfNotExactlyFound(request);        if(weatherGridCells.isEmpty()) {            throw Status.NOT_FOUND                    .withDescription("No grid metrics found within the requested time or any past historical buckets.")                    .asRuntimeException();        }        Map<String, GridCellLayers> cellLayersMap = convertGridCellLayersListToMap(weatherGridCells);        return WeatherMap.newBuilder()                .setIntervalMinutes(request.getTimeIntervalInMinutes())                .setTimestampBucket(request.getTimestampBucket())                .putAllGridCells(cellLayersMap)                .build();    }    private @NonNull List<WeatherGridCellLayer> getGridCellLayersWithExpandedAlgorithmIfNotExactlyFound(SpatialBoxRequest request) {        List<WeatherGridCellLayer> weatherGridCells = List.of();        SpatialBoxRequest expandedRequest = request;        for(int i = 0; i<4; i++) {            weatherGridCells = getWeatherGridCellMetrics(expandedRequest);            if(!weatherGridCells.isEmpty()) {                break;            }            expandedRequest = expandRequestSpatialBoxByTier(expandedRequest, i);        }        return weatherGridCells;    }    private @NonNull List<WeatherGridCellLayer> getWeatherGridCellMetrics(@NonNull SpatialBoxRequest request) {        List<WeatherGridCellLayer> weatherGridCells = tryToFindGridCellLayersByCurrentTimestamp(request);        if(!weatherGridCells.isEmpty()) {            return weatherGridCells;        }        return tryToFindClosestGridCellLayersToCurrentTimestamp(request);    }    private @NonNull List<WeatherGridCellLayer> tryToFindClosestGridCellLayersToCurrentTimestamp(@NonNull SpatialBoxRequest request) {        List<WeatherMapBucket> pastBuckets = historicalQueryRepository.findAllPastBuckets(request);        List<WeatherGridCellLayer> weatherGridCellLayers = List.of();        int pastBucketsSize = pastBuckets.size();        for(int i = 0; (i<pastBucketsSize && weatherGridCellLayers.isEmpty()); i++) {            WeatherMapBucket pastBucket = pastBuckets.get(i);            UUID pastBucketId = pastBucket.getId();            log.info("Evaluating past bucket ID: {} from timestamp: {}", pastBucketId, pastBucket.getTimestampBucket());            weatherGridCellLayers = historicalQueryRepository.findGridCellLayersByBucketIdAndSpatialBox(pastBucketId, request);        }        return weatherGridCellLayers;    }    private List<WeatherGridCellLayer> tryToFindGridCellLayersByCurrentTimestamp(@NonNull SpatialBoxRequest request) {        Optional<UUID> optionalUUID = resolveBucketIdFromCache(request);        if(optionalUUID.isEmpty()) {            optionalUUID = resolveBucketIdFromDb(request);        }        List<WeatherGridCellLayer> weatherGridCells = List.of();        if(optionalUUID.isPresent()) {            weatherGridCells = historicalQueryRepository.findGridCellLayersByBucketIdAndSpatialBox(optionalUUID.get(), request);        }        return weatherGridCells;    }    private Optional<UUID> resolveBucketIdFromCache(@NonNull SpatialBoxRequest request) {        WeatherMapBucketCacheDto cachedBucket = getL1BucketCache(springL1CacheManager)                .get(getBucketIdFromSpatialBoxRequest(request), WeatherMapBucketCacheDto.class);        if(cachedBucket==null) {            return Optional.empty();        }        return Optional.of(cachedBucket.id());    }    private Optional<UUID> resolveBucketIdFromDb(@NonNull SpatialBoxRequest request) {        Optional<WeatherMapBucket> optionalWeatherMapBucket = historicalQueryRepository.findWeatherBucketByTimestampAndIntervalMinutes(request);        if(optionalWeatherMapBucket.isEmpty()) {            return Optional.empty();        }        WeatherMapBucket weatherMapBucket = optionalWeatherMapBucket.get();        WeatherMapBucketCacheDto dtoToCache = createWeatherMapBucketCacheDtoFromWeatherMapBucket(weatherMapBucket);        getL1BucketCache(springL1CacheManager).put(getBucketIdFromSpatialBoxRequest(request), dtoToCache);        return Optional.of(weatherMapBucket.getId());    }    private @NonNull WeatherMapBucketCacheDto createWeatherMapBucketCacheDtoFromWeatherMapBucket(WeatherMapBucket weatherMapBucket) {        return new WeatherMapBucketCacheDto(                weatherMapBucket.getId(),                weatherMapBucket.getTimestampBucket(),                weatherMapBucket.getIntervalMinutes(),                weatherMapBucket.getVersion()        );    }    private @NonNull Map<String, GridCellLayers> convertGridCellLayersListToMap(@NonNull List<WeatherGridCellLayer> weatherGridCells) {        return weatherGridCells.stream()                .collect(Collectors.toMap(                        WeatherGridCellLayer::getGeohash,                        weatherMapConverter::convertWeatherGridCellsToWeatherMap,                        (existing, replacement) -> existing                ));    }    private void proceedFailedResponse(StreamObserver<WeatherMap> responseObserver, Exception e, String errMsg) {        Status status = Status.INTERNAL;        if(e instanceof StatusRuntimeException && e.getMessage().contains(Status.Code.NOT_FOUND.name())) {            status = Status.NOT_FOUND;        }        log.error(errMsg);        responseObserver.onError(status                .withDescription(errMsg)                .withCause(e)                .asRuntimeException());    }}